import math
from fractions import Fraction as F
def rising(v,n): return math.prod(v+i for i in range(n))
def cvec(g,a): return [math.comb(g,j)*(-1)**(g-j)*rising(a,g-j)*rising(4-a,j) for j in range(g+1)]
def pvec(g,a,m):
 c=cvec(g,a); return [m*c[0]]+[(m+j)*c[j]+(m+j-1-g)*c[j-1] for j in range(1,g+1)]+[m*c[g]]
def col(g,a,m):
 d=1-g-(a+m); s=-a-g if d>0 else -a-g+abs(d); sg=1 if d>0 else -1
 return {s+j:sg*x for j,x in enumerate(pvec(g,a,m)) if x}
def comp(g,k,q):
 cen=1-g; return [col(g,a,m) for a in range(0,2*k+1,2) for m in (cen-q-a,cen+q-a)]
def defect(g,a,q):
 c=cvec(g,a); J=[c[0]]+[c[j]+c[j-1] for j in range(1,g+1)]+[c[g]]; out={}
 for s,sg in [(-a-g,-2),(-a-g+q+2,2)]:
  for j,x in enumerate(J): out[s+j]=out.get(s+j,0)+sg*x
 return {r:x for r,x in out.items() if x}
def rank(M):
 A=[[F(x) for x in row] for row in M]; m=len(A); n=len(A[0]) if m else 0; r=0
 for c in range(n):
  p=next((i for i in range(r,m) if A[i][c]),None)
  if p is None: continue
  A[r],A[p]=A[p],A[r]; z=A[r][c]; A[r]=[x/z for x in A[r]]
  for i in range(r+1,m):
   if A[i][c]:
    z=A[i][c]; A[i]=[A[i][j]-z*A[r][j] for j in range(c,n)]
  r+=1
  if r==m: break
 return r
def member(cols,v):
 rows=sorted(set(v)|{r for c in cols for r in c}); A=[[c.get(r,0) for c in cols] for r in rows]; b=[v.get(r,0) for r in rows]
 return rank(A)==rank([row+[b[i]] for i,row in enumerate(A)])
res=[]
for g in range(2,9):
 for q in range(1,9):
  for a in range(0,9,2):
   flags=[member(comp(g,K,q+2),defect(g,a,q)) for K in range(max(2,a//2),13)]
   res.append((g,q,a,flags))
print('cases',len(res),'ever_in',sum(any(x[3]) for x in res),'never_in',sum(not any(x[3]) for x in res))
print('first_ever',next((x for x in res if any(x[3])),None))
print('first_never',next((x for x in res if not any(x[3])),None))
